static int open_terminal(const char *tty_path) {
    FILE *fp = fopen(tty_path, "r+");
    if (!fp) {
        printf("cmatrix: error: '%s' couldn't be opened: No such file or directory.\n", tty_path);
        return -1;
    }
    return 0;
}
