static int get_terminal_size(FILE *fp, int *cols, int *rows) {
    struct winsize ws;
    if (ioctl(fileno(fp), TIOCGWINSZ, &ws) == 0) {
        *cols = ws.ws_col;
        *rows = ws.ws_row;
        return 0;
    }
    *cols = 80;
    *rows = 24;
    return 0;
}
```

