int main(int argc, char *argv[]) {
    FILE *fp = NULL;
    int cols = 80, rows = 24;
    int *matrix = NULL;
    int *shadows = NULL;
    int *chars = NULL;
    int *colors = NULL;
    int *bold_flags = NULL;
    int *lambda_flags = NULL;
