    } else {
        fprintf(fp, "\033[?25l");
    }
    fflush(fp);
}

int main(int argc, char *argv[]) {
    FILE *fp = NULL;
    int cols = 80, rows = 24;
    int *matrix = NULL;
    int *shadows = NULL;
    int *chars = NULL;
    int *colors = NULL;
    int *bold_flags = NULL;
    int *lambda_flags = NULL;
    int i, j;
    struct timeval tv;
    fd_set readfds;
    int color_idx = 0;
    int has_error = 0;

    parse_args(argc, argv);

    if (should_exit) {
        return 0;
    }

    if (open_terminal(tty_path) != 0) {
        return 1;
    }

    if (get_terminal_size(fp, &cols, &rows) != 0) {
        cols = 80;
        rows = 24;
    }

    matrix = (int *)malloc(cols * rows * sizeof(int));
    shadows = (int *)malloc(cols * rows * sizeof(int));
    chars = (int *)malloc(cols * rows * sizeof(int));
    colors = (int *)malloc(cols * rows * sizeof(int));
    bold_flags = (int *)malloc(cols * rows * sizeof(int));
    lambda_flags = (int *)malloc(cols * rows * sizeof(int));

    if (!matrix || !shadows || !chars || !colors || !bold_flags || !lambda_flags) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (i = 0; i < cols * rows; i++) {
        matrix[i] = 0;
        shadows[i] = 0;
        chars[i] = 0;
        colors[i] = 0;
        bold_flags[i] = 0;
        lambda_flags[i] = 0;
    }

    clear_screen(fp);
    set_cursor_visible(fp, 0);

    if (use_message) {
        fprintf(fp, "\033[?25h");
        fprintf(fp, "\033[H");
        fprintf(fp, "%s\n", message);
        fprintf(fp, "\033[?25l");
    }

    while (1) {
        if (screensaver_mode) {
            // Check for keystroke
            FD_ZERO(&readfds);
            FD_SET(STDIN_FILENO, &readfds);
            tv.tv_sec = 0;
            tv.tv_usec = 100000;
            if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv) > 0) {
                break;
            }
        }

        // Update matrix
        for (i = 0; i < cols * rows; i++) {
            if (matrix[i] == 1) {
                matrix[i] = 0;
            }
        }

        // Draw matrix
        for (i = 0; i < rows; i++) {
            for (j = 0; j < cols; j++) {
                int idx = i * cols + j;
                if (matrix[idx] == 1) {
                    if (rainbow_mode) {
                        int r = (time(NULL) + idx) % 256;
                        int g = (time(NULL) + idx + 85) % 256;
                        int b = (time(NULL) + idx + 170) % 256;
                        fprintf(fp, "\033[38;2;%d;%d;%dm", r, g, b);
                    } else if (lambda_mode) {
                        fprintf(fp, "\033[38;5;216mλ\033[0m");
                    } else {
                        fprintf(fp, "\033[38;5;%dm*\033[0m", colors[idx] + 10);
                    }
                } else {
                    fprintf(fp, " ");
                }
            }
            fprintf(fp, "\n");
        }

        // Wait for delay
        tv.tv_sec = 0;
        tv.tv_usec = delay * 100000;
        select(STDIN_FILENO + 1, NULL, NULL, NULL, &tv);
    }

    // Cleanup
    if (matrix) free(matrix);
    if (shadows) free(shadows);
    if (chars) free(chars);
    if (colors) free(colors);
    if (bold_flags) free(bold_flags);
    if (lambda_flags) free(lambda_flags);

    return 0;
}
EOF"}

